@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="HandleChannelSelected" />

    <MessageArea ChannelName="@currentChannelName"
                 ChannelDescription="@currentChannelDescription"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingOlder="isLoadingOlder"
                 OnLoadOlderMessages="LoadOlderMessages"
                 OnSendMessage="HandleSendMessage"
                 OnOpenThread="HandleOpenThread"
                 OnReact="HandleReact" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="HandleCloseThread"
                     OnSendReply="HandleSendReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private int selectedChannelId;
    private string currentChannelName = string.Empty;
    private string currentChannelDescription = string.Empty;

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    // Pagination
    private const int PageSize = 30;
    private int currentSkip;
    private bool isLoadingOlder;
    private bool hasMoreMessages = true;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        await SelectChannel(channel);
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannelId = channel.Id;
        currentChannelName = channel.Name;
        currentChannelDescription = channel.Description;
        currentSkip = 0;
        hasMoreMessages = true;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        currentSkip = messages.Count;

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new { RootId = m.Id, Replies = messages.Where(r => r.ReplyToId == m.Id).ToList() })
            .Where(x => x.Replies.Count > 0)
            .Select(x => new ThreadSummary(x.RootId, x.Replies.Count, x.Replies.Max(r => r.SentAt)))
            .ToList();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingOlder || !hasMoreMessages) return;

        isLoadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, currentSkip, PageSize);
        if (older.Count < PageSize)
        {
            hasMoreMessages = false;
        }

        messages.InsertRange(0, older);
        currentSkip += older.Count;
        isLoadingOlder = false;
    }

    private async Task HandleSendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(sent);
    }

    private async Task HandleOpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void HandleCloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task HandleSendReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessage.Id);
        var summary = new ThreadSummary(threadRootMessage.Id, threadReplies.Count, reply.SentAt);
        if (existing >= 0)
            threadSummaries[existing] = summary;
        else
            threadSummaries.Add(summary);
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Update local state
        var msg = messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existingReaction = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existingReaction is not null)
            {
                existingReaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, new List<string> { "You" }));
            }
        }
    }
}

