{"file_text": ".chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    padding: 1rem;
    overflow-y: auto;
    border-right: 1px solid #1e1f22;
}

::deep .sidebar-title {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #949ba4;
    margin-bottom: 0.75rem;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

::deep .channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.25rem;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0.1rem 0.4rem;
    border-radius: 9px;
    min-width: 1.2rem;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: #313338;
    color: #f2f3f5;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #949ba4;
    font-size: 0.85rem;
}

/* Message Bubble */
::deep .message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #2e3035;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

::deep .message-content {
    margin-top: 0.2rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .reactions-row {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 4px;
    padding: 0.15rem 0.4rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #f2f3f5;
}

::deep .reaction-badge:hover {
    border-color: #5865f2;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 4px;
    padding: 0.2rem;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 6px;
    padding: 0.3rem;
    z-index: 10;
}

::deep .emoji-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 3px;
}

::deep .emoji-btn:hover {
    background: #404249;
}

/* Message Input */
::deep .message-input {
    padding: 0.75rem 1rem;
    border-top: 1px solid #1e1f22;
    display: flex;
    gap: 0.5rem;
    align-items: flex-end;
    flex-shrink: 0;
}

::deep .message-textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #f2f3f5;
    padding: 0.6rem 0.75rem;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
    outline: none;
}

::deep .message-textarea:focus {
    box-shadow: 0 0 0 1px #5865f2;
}

::deep .send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 0.5rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

::deep .send-btn:not(:disabled):hover {
    background: #4752c4;
}

/* Thread Panel */
::deep .thread-panel {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: #2b2d31;
    color: #f2f3f5;
    border-left: 1px solid #1e1f22;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 3px;
}

::deep .close-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    background: #232428;
}

::deep .thread-root-message .message-author {
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
}
